var archiveNodes = build.FindChildrenRecursive<BaseNode>()
    .Where(n => n.GetType().Name.Contains("Archive") || n.GetType().Name.Contains("Embed"))
    .ToList();

Console.WriteLine($"Archive nodes found: {archiveNodes.Count}");
foreach (var n in archiveNodes.Take(5))
    Console.WriteLine($"  Type: {n.GetType().Name}");

// Try ArchiveFile
var archiveFiles = build.FindChildrenRecursive<BaseNode>()
    .Where(n => n.GetType().Name == "ArchiveFile")
    .ToList();
Console.WriteLine($"\nArchiveFile nodes: {archiveFiles.Count}");

// List all node types
var types = build.FindChildrenRecursive<BaseNode>()
    .Select(n => n.GetType().Name)
    .Distinct()
    .OrderBy(x => x)
    .ToList();
Console.WriteLine("\nAll node types:");
foreach (var t in types)
    Console.WriteLine($"  {t}");
EOF

