cat > /tmp/parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-0a5b189c2bb5469384be435cc6fc5b0a/build.binlog");

// Get full details of each error
var errors = build.FindChildrenRecursive<Error>().ToList();
foreach (var e in errors)
{
    var project = e.GetNearestParent<Project>();
    Console.WriteLine($"Project: {project?.Name}");
    Console.WriteLine($"Code: {e.Code}");
    Console.WriteLine($"File: {e.File}");
    Console.WriteLine($"Line: {e.LineNumber}, Col: {e.ColumnNumber}");
    Console.WriteLine($"Text: {e.Text}");
    Console.WriteLine($"Subcategory: {e.Subcategory}");
    Console.WriteLine("---");
}

// Check if Api project had a build at all - look for targets
Console.WriteLine("\n=== Api project build status ===");
var apiProjects = build.FindChildrenRecursive<Project>().Where(p => p.Name.Contains("Api")).ToList();
foreach (var ap in apiProjects)
{
    var targets = ap.FindChildrenRecursive<Target>().ToList();
    var coreCmpTarget = targets.FirstOrDefault(t => t.Name == "CoreCompile");
    var buildTarget = targets.FirstOrDefault(t => t.Name == "Build");
    Console.WriteLine($"  Project: {ap.Name}, Targets: {targets.Count}, CoreCompile: {coreCmpTarget != null}, Build: {buildTarget != null}");
    if (buildTarget != null)
        Console.WriteLine($"    Build target children: {buildTarget.Children.Count}");

    // Check for any "skipped" messages
    var skipped = ap.FindChildrenRecursive<Message>().Where(m => m.Text != null && m.Text.Contains("not build")).ToList();
    foreach (var s in skipped)
        Console.WriteLine($"    Skipped msg: {s.Text}");
}
EOF

